function [s_out,y_out,X_p,Y_p,theta_out,working] = Map_loc_GPS(Lat,Lon)working = 0;%%% -------- Hp di acquisizione GPS coerentes_out=-1;y_out=-1;X_p=-1;Y_p=-1;theta_out=-1;map_data = coder.load('PL_jrl_chs.mat');% map_data = coder.load('LP_jrl_chs.mat');[x,y,~] = deg2utm(Lat,Lon);X_out=x;Y_out=y;%%% -------- Ricollocamento sulla mappa%%% NB: no uso dell'informazione passata%%%     no ottimizzazione della ricerca sulla mappaveh_state= struct('s',-1,'y',-1,'dist',1e2,'ID',-1);%%% test #1veh_state.ID = -1; % inizializzofor i=1:length(map_data.map_road.s)    dist_temp = (x-map_data.map_road.X(i))^2 + (y-map_data.map_road.Y(i))^2;    if dist_temp <= veh_state.dist        veh_state.dist = dist_temp;        veh_state.ID = i;    endend%%% definire quali segmenti guardareif veh_state.ID == -1    disp('error_1')    s_out=-1;    y_out=0;else    if veh_state.ID == 1 | veh_state.ID == size(map_data.map_road.s,1)        lf_id = [size(map_data.map_road.s,1)-1 1];        rg_id = [size(map_data.map_road.s,1) 2];    else        lf_id = [veh_state.ID-1 veh_state.ID];        rg_id = [veh_state.ID veh_state.ID+1];    end    %%% -------- scrittura dell'uscita adeguata[find_check_1, f_min_1, s_act_1, y_act_1] = look_segment(x, y, map_data.map_road,lf_id(1),rg_id(1));[find_check_2, f_min_2, s_act_2, y_act_2] = look_segment(x, y, map_data.map_road,lf_id(2),rg_id(2));if find_check_1 == 1     s_out=s_act_1;    y_out=y_act_1;%     lf_index = find_check_1else     s_out=s_act_2;    y_out=y_act_2;endif s_out ==-1    disp('errore grave non funziona il riconoscimento nel segmento')end[X_p,Y_p,theta_out] = Map_loc(map_data.map_road,s_out);working = 1;end